-- Placeholder "coming soon" CBT entries for every course in UNN's most
-- recent official CBT examination timetable (2021/2022 Second Semester,
-- held July-August 2023 -- Nigerian public-university calendars run
-- years behind the nominal session name; this is genuinely the latest
-- one UNN has posted) that Eduvora does not already have a real CBT
-- bank for.
--
-- 162 subjects, one placeholder question each ("this paper is
-- coming soon"), so each shows up as a real (near-empty) entry in the
-- app's CBT list rather than not existing at all -- per explicit
-- instruction, since a subject with zero question rows would not
-- appear in the list (subjects are derived from grouping existing
-- cbt_questions rows).
--
-- Faculty tags are best-effort from the timetable's own department
-- names (not cross-checked against course_outlines row by row -- most
-- of these ~150 courses, especially Medicine/Nursing/Radiography, have
-- no course_outlines entry in this database at all yet). Level derived
-- from the course code's leading digit. Semester set to "second"
-- matching the source document's own title -- these were not
-- individually verified against each department's real semester
-- placement.
--
-- Skipped: courses that already have a real CBT bank (PHY111/112/114/
-- 115/116/121/122/124, MTH101/102/103/206/208, COS101/201, GST212) and
-- blank/illegible rows in the source table.

insert into public.cbt_questions
  (subject_id, subject_name, institution, faculty, department, level,
   question, options, correct_index, explanation, topic, is_general,
   semester, units)
